class Solution {
public:
    string shortestPalindrome(string s) {
        int n = s.length();
        if (n <= 1) return s;

        long long base = 131;
        long long mod1 = 1000000007;
        long long mod2 = 1000000009;

        long long hash1 = 0, rhash1 = 0;
        long long hash2 = 0, rhash2 = 0;
        long long power1 = 1, power2 = 1;

        int best = 0;
        for (int i = 0; i < n; ++i) {
            int c = s[i] - 'a' + 1;
            hash1 = (hash1 * base + c) % mod1;
            rhash1 = (rhash1 + c * power1) % mod1;
            power1 = (power1 * base) % mod1;

            hash2 = (hash2 * base + c) % mod2;
            rhash2 = (rhash2 + c * power2) % mod2;
            power2 = (power2 * base) % mod2;

            if (hash1 == rhash1 && hash2 == rhash2) {
                best = i + 1;
            }
        }

        string res;
        res.reserve(2 * n - best);
        for (int i = n - 1; i >= best; --i) {
            res += s[i];
        }
        res += s;
        return res;
    }
};
